decide(subject, op, resource):
    try:
        grant = grants.find(subject, op, resource)   # explicit positive facts
    except PolicyError:
        deny(subject, op, resource)                  # any lookup failure denies
    if grant is None:
        deny(subject, op, resource)                  # no grant -> no access
    return grant
# every protected operation starts with decide(); an operation with no
# configured grant is denied by construction
